solution:
%dw 2.0
output application/json
---
do {
  var amounts = payload.lines.amount
  var total = sum(amounts)
  var shares = amounts map floor(payload.discount * $ / total)
  var left = payload.discount - sum(shares)
  var top = amounts indexOf max(amounts)
  ---
  payload.lines map { sku: $.sku, discount: shares[$$] + (if ($$ == top) left else 0) }
}

